function u6BindGame(g,d){
 if(g.mode==='pick')document.querySelectorAll('[data-u6-pick]').forEach(b=>b.onclick=()=>{const r=g.rounds[d.round],j=Number(b.dataset.u6Pick);if(d.answers[d.round]==null)d.answers[d.round]=j;if(j!==r.correct){d.errors++;d.feedback='ลองดูภาพและคำบอกอีกที';persist();u6RenderGame();return}d.round++;d.feedback='ถูกแล้ว!';persist();if(d.round>=g.rounds.length)u6Complete(10*g.rounds.filter((x,i)=>d.answers[i]===x.correct).length/g.rounds.length,{answers:[...d.answers]});else u6RenderGame()});
 if(g.mode==='order'){document.querySelectorAll('[data-u6-order]').forEach(b=>b.onclick=()=>{d.chosen.push(Number(b.dataset.u6Order));d.feedback='';persist();u6RenderGame()});$('#u6-order-clear').onclick=()=>{d.chosen=[];d.feedback='';persist();u6RenderGame()};$('#u6-order-check').onclick=()=>{if(d.chosen.every((v,i)=>v===i)){u6Complete(10-Math.min(6,d.errors*2),{order:[...d.chosen]})}else{d.errors++;d.feedback='ลำดับนี้ยังทำตามไม่ได้ ลองสลับภาพ';d.chosen=[];persist();u6RenderGame()}}}
 if(g.mode==='match'){document.querySelectorAll('[data-u6-left]').forEach(b=>b.onclick=()=>{d.left=Number(b.dataset.u6Left);u6RenderGame()});document.querySelectorAll('[data-u6-right]').forEach(b=>b.onclick=()=>{if(d.left==null){d.feedback='แตะภาพด้านซ้ายก่อน';u6RenderGame();return}const j=Number(b.dataset.u6Right);if(j===d.left){d.pairs.push(j);d.left=null;d.feedback='จับคู่ถูกแล้ว';persist();if(d.pairs.length===g.pairs.length)u6Complete(10-Math.min(6,d.errors*2));else u6RenderGame()}else{d.errors++;d.feedback='ลายหรือชนิดยังไม่ตรง ลองอีกคู่';persist();u6RenderGame()}})}
 if(g.mode==='sort')document.querySelectorAll('[data-u6-bin]').forEach(b=>b.onclick=()=>{const j=Number(b.dataset.u6Bin),item=g.items[d.sort.length];if(j===item[2]){d.sort.push(j);d.feedback='ถูกกลุ่มแล้ว';persist();if(d.sort.length===g.items.length)u6Complete(10-Math.min(6,d.errors*2));else u6RenderGame()}else{d.errors++;d.feedback='ลองดูหน้าที่ของชิ้นนี้อีกที';persist();u6RenderGame()}});
 if(g.mode==='grid'){document.querySelectorAll('[data-u6-cell]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.u6Cell),at=d.path.at(-1),adj=Math.abs(i-at)===4||(Math.floor(i/4)===Math.floor(at/4)&&Math.abs(i-at)===1);if(!adj){d.errors++;d.feedback='เดินได้ทีละช่องที่ติดกัน';u6RenderGame();return}if(g.walls.includes(i)){d.errors++;d.feedback='ช่องนี้มีสิ่งกีดขวาง';u6RenderGame();return}d.path.push(i);d.feedback='';persist();if(i===g.goal){if(g.checkpoint!=null&&!d.path.includes(g.checkpoint)){d.errors++;d.feedback='ต้องผ่านจุดรับโล่ก่อนถึงประตู';u6RenderGame()}else u6Complete(10-Math.min(6,d.errors),{path:[...d.path]})}else u6RenderGame()});$('#u6-grid-clear').onclick=()=>{d.path=[0];d.feedback='เริ่มทางใหม่';persist();u6RenderGame()}}
 if(g.mode==='command'){document.querySelectorAll('[data-u6-arrow]').forEach(b=>b.onclick=()=>{if(d.code.length>=g.max){d.feedback='ลูกศรเต็มแล้ว ลองทดลองหรือเอาออก';u6RenderGame();return}d.code.push(b.dataset.u6Arrow);d.feedback='';persist();u6RenderGame()});$('#u6-command-undo').onclick=()=>{d.code.pop();d.feedback='';persist();u6RenderGame()};$('#u6-command-run').onclick=()=>{let p=g.start,valid=true;for(const cmd of d.code){const row=Math.floor(p/g.grid),col=p%g.grid,next=cmd==='U'?p-g.grid:cmd==='D'?p+g.grid:cmd==='L'?p-1:p+1;if(next<0||next>=g.grid*g.grid||(cmd==='L'&&col===0)||(cmd==='R'&&col===g.grid-1)||g.blocks.includes(next)){valid=false;break}p=next}d.commandEnd=p;if(valid&&p===g.goal){u6Complete(10-Math.min(6,d.errors*2),{commands:[...d.code]})}else{d.errors++;d.feedback=valid?`ไปถึงช่อง ${p+1} ยังไม่ใช่ประตู ลองแก้ลูกศร`:'คำสั่งพาไปช่องที่เดินไม่ได้ ลองแก้ลูกศร';persist();u6RenderGame()}}}
 if(g.mode==='search')document.querySelectorAll('[data-u6-search]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.u6Search);if(d.open.includes(i))return;d.open.push(i);d.feedback=g.targets.includes(i)?'พบของที่หาแล้ว!':'ช่องนี้ยังไม่ใช่ของที่หา';persist();const found=g.targets.every(x=>d.open.includes(x)),coverage=u6Unit===7&&u6TopicIndex(u6Unit,u6Stage)===2;if(found&&(!coverage||d.open.length===g.items.length))u6Complete(Math.max(5,10-Math.floor((d.open.length-g.targets.length)/3)),{opened:[...d.open]});else u6RenderGame()});
 if(g.mode==='type'){$('#u6-code-input').focus({preventScroll:true});$('#u6-code-check').onclick=()=>{const wanted=g.codes[d.round],actual=$('#u6-code-input').value.trim();if(actual.toLocaleLowerCase()===wanted.toLocaleLowerCase()){if(u6Unit===9)u6Data(9).fileName=actual;d.round++;d.feedback='ตรงแล้ว';persist();if(d.round>=g.codes.length)u6Complete(10-Math.min(6,d.errors*2),{codes:g.codes});else u6RenderGame()}else{d.errors++;d.feedback='ยังไม่ตรง ลองดูทีละตัวและแก้ได้';persist();u6RenderGame()}};$('#u6-code-input').onkeydown=e=>{if(e.key==='Enter')$('#u6-code-check').click()}}
 if(g.mode==='paint'||g.mode==='reopen')u6BindCanvas(g,d);
 if(g.mode==='save'){if($('#u6-download'))$('#u6-download').onclick=()=>{const a=document.createElement('a');a.href=u6Data(u6Unit).artifact.image;a.download='Techno-P1-ภาพสถานี.png';a.click()};if($('#u6-save-confirm'))$('#u6-save-confirm').onclick=()=>u6Complete(10,{artifactSaved:true});if($('#u6-back-draw'))$('#u6-back-draw').onclick=()=>u6Open(9,3)}
 if(g.mode==='real'){document.querySelectorAll('[data-u6-real]').forEach(b=>b.onchange=()=>{d.real=d.real||{};d.real[b.dataset.u6Real]=b.checked;persist()});$('#u6-real-done').onclick=()=>{if(!g.checks.every((_,i)=>d.real?.[i])){d.feedback='ทำให้ครบทุกข้อ แล้วแตะเครื่องหมายถูก';u6RenderGame();return}u6Data(u6Unit).realConfirm=u6Data(u6Unit).realConfirm||{};u6Data(u6Unit).realConfirm[u6Stage]={confirmed:false,at:new Date().toISOString()};u6Complete(5,{selfReported:true,pendingTeacher:true})}}
}
function u6BindCanvas(g,d){const canvas=$('#u6-canvas'),ctx=canvas.getContext('2d'),saved=g.mode==='reopen'?u6Data(9).artifact?.image:d.image;ctx.fillStyle='#ffffff';ctx.fillRect(0,0,canvas.width,canvas.height);if(saved){const img=new Image();img.onload=()=>ctx.drawImage(img,0,0,canvas.width,canvas.height);img.src=saved}let tool=d.tool||'a06-01',drawing=false;document.querySelectorAll('[data-u6-stamp]').forEach(b=>b.onclick=()=>{tool=b.dataset.u6Stamp;d.tool=tool;document.querySelectorAll('[data-u6-stamp]').forEach(x=>x.classList.toggle('selected',x===b))});const point=e=>{const r=canvas.getBoundingClientRect();return {x:(e.clientX-r.left)*canvas.width/r.width,y:(e.clientY-r.top)*canvas.height/r.height}};canvas.onpointerdown=e=>{e.preventDefault();canvas.setPointerCapture(e.pointerId);const p=point(e);if(tool==='pen'){drawing=true;ctx.strokeStyle='#ef2895';ctx.lineWidth=7;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(p.x,p.y)}else{const img=new Image();img.onload=()=>{ctx.drawImage(img,p.x-38,p.y-38,76,76);d.image=canvas.toDataURL('image/png');persist()};img.src=u6Art(tool);d.stampCount=(d.stampCount||0)+1;$('#u6-stamp-count').textContent=`วางภาพแล้ว ${d.stampCount} ชิ้น`;$('#u6-paint-done').disabled=d.stampCount<(g.need||1)}};canvas.onpointermove=e=>{if(!drawing)return;const p=point(e);ctx.lineTo(p.x,p.y);ctx.stroke()};canvas.onpointerup=()=>{if(drawing){drawing=false;d.stampCount=(d.stampCount||0)+1;$('#u6-stamp-count').textContent=`วางภาพแล้ว ${d.stampCount} ชิ้น`;$('#u6-paint-done').disabled=d.stampCount<(g.need||1);d.image=canvas.toDataURL('image/png');persist()}};$('#u6-paint-done').onclick=()=>{const image=canvas.toDataURL('image/png');d.image=image;const unit=u6Data(9);unit.artifact={image,name:unit.fileName||'สถานีของฉัน',at:new Date().toISOString()};persist();u6Complete(10,{artifactSaved:true,stampCount:d.stampCount})}}
function u6RenderReal(){const p=u6StagePages(u6Unit,u6Stage)[0],d=u6Data(u6Unit),done=Boolean(d.stageScores[u6Stage]);$('#u6-page').innerHTML=`<div class="u6-intro">${u6Img(u6Scene(u6Unit),'Techno ชวนลงมือ','u6-scene')}<div><span class="academic-kicker">ภารกิจนอกจอ</span><h2>ลองทำกับเพื่อน</h2><p>${esc(p.content)}</p></div></div><div class="u6-real-note"><h3>ทำแบบนี้นะ</h3><p>ทำกับเพื่อนหรือคุณครู แล้วเล่าให้ฟังว่าเราทำอะไร</p><label><input type="checkbox" id="u6-real-confirm" ${done?'checked':''}> ฉันได้ลองทำและเล่าให้เพื่อนหรือครูฟังแล้ว</label></div><button class="primary" id="u6-real-next">${done?'ไปต่อ →':'บันทึกการเข้าร่วม →'}</button><p class="small">ครูจะมาดูตอนเราทำจริง</p>`;$('#u6-real-next').onclick=()=>{if(!done){if(!$('#u6-real-confirm').checked){toast('ลองทำและเล่าก่อนนะ');return}u6Record('real-participation',1,1,{selfReported:true});u6Award(5,'participation')}u6Next()}}
function u6RenderReflect(){const d=u6Data(u6Unit);$('#u6-page').innerHTML=`<div class="u6-intro">${u6Img(u6Scene(u6Unit),'Techno ชวนทบทวน','u6-scene')}<div><span class="academic-kicker">ทบทวนก่อนสู้บอส</span><h2>วันนี้เราเรียนรู้อะไร?</h2><p>แตะสิ่งที่ตรงกับเรา แล้วเล่าให้ครูฟัง</p></div></div><div class="u6-reflect">${['ทำได้ด้วยตัวเอง','อยากลองอีกครั้ง','ขอให้เพื่อนช่วย'].map((x,i)=>`<button data-u6-reflect="${i}" class="${d.reflection===i?'selected':''}">${esc(x)}</button>`).join('')}</div><div class="u6-real-note"><b>ลองเล่า:</b> ${esc(u6Plan(u6Unit).objectives[0]||'เราแก้ปัญหาอย่างไร')}</div><button class="primary" id="u6-reflect-next" ${d.reflection==null?'disabled':''}>ไปสู้บอส →</button>`;document.querySelectorAll('[data-u6-reflect]').forEach(b=>b.onclick=()=>{d.reflection=Number(b.dataset.u6Reflect);persist();u6RenderReflect()});$('#u6-reflect-next').onclick=()=>{if(!d.stageScores[u6Stage]){u6Record('reflection',1,1,{choice:d.reflection});u6Award(10,'participation')}u6Next()}}
function u6StopBoss(){if(u6BossTimer){clearInterval(u6BossTimer);u6BossTimer=null}}
function u6BossDraft(){const d=u6Data(u6Unit);return d.bossDraft||(d.bossDraft={round:0,hits:0,misses:0,seconds:15,running:false,finished:false})}
function u6RenderBoss(){const d=u6Data(u6Unit),b=u6BossDraft();$('#u6-page').innerHTML=`<div class="u6-boss-head"><div><span class="academic-kicker">BOSS · ภารกิจ ${u6Unit}</span><h2>สู้บอสด้วยความรู้!</h2><p>ตอบให้ถูก 3 จาก 4 ครั้งเพื่อช่วย Techno</p></div><div class="u6-boss-stats">บอส <b id="u6-boss-hp">${4-b.hits}/4</b> · Techno <b id="u6-rider-hp">${3-b.misses}/3</b></div></div><div class="u6-boss-arena" id="u6-boss-arena"><div class="u6-boss-sprite" id="u6-boss-sprite" role="img" aria-label="บอส Golden Parasite" style="background-image:url('${ASSETS.boss}')"></div>${u6Img('techno-welcome','Maskrider Techno','u6-boss-rider')}<div class="u6-boss-flash" id="u6-boss-flash"></div></div><div id="u6-boss-controls"></div><button class="quiet" id="u6-boss-skip">ข้ามเกมบอส · ไปดูผล</button>`;$('#u6-boss-skip').onclick=()=>{u6StopBoss();u6BossFinish(false,true)};if(b.finished)u6BossFinishView();else if(!b.running){$('#u6-boss-controls').innerHTML=`<div class="u6-boss-call"><h3>พร้อมช่วย Techno หรือยัง?</h3><p>เลือกคำตอบก่อนหมดเวลา บอสจะโจมตีถ้าตอบผิด</p><button class="primary" id="u6-boss-start">เริ่มสู้ →</button></div>`;$('#u6-boss-start').onclick=()=>{b.running=true;b.seconds=15;persist();u6BossTurn()}}else u6BossTurn()}
function u6BossTurn(){const b=u6BossDraft();if(b.finished)return u6BossFinishView();const q=U6_UNIT_QUIZZES[u6Unit].post[b.round%4];$('#u6-boss-controls').innerHTML=`<div class="u6-boss-question"><div class="u6-boss-clock" id="u6-boss-clock">${b.seconds} วินาที</div><h3>${esc(q[0])}</h3><div>${q[1].map((x,i)=>`<button data-u6-boss-answer="${i}">${esc(x)}</button>`).join('')}</div><p>ครั้งที่ ${b.round+1}/4</p></div>`;$('#u6-boss-hp').textContent=`${4-b.hits}/4`;$('#u6-rider-hp').textContent=`${3-b.misses}/3`;document.querySelectorAll('[data-u6-boss-answer]').forEach(x=>x.onclick=()=>u6BossAnswer(Number(x.dataset.u6BossAnswer)));u6StopBoss();u6BossTimer=setInterval(()=>{if(!$('#u6-boss-clock'))return u6StopBoss();b.seconds--;$('#u6-boss-clock').textContent=`${b.seconds} วินาที`;if(b.seconds<=0)u6BossAnswer(-1)},1000)}
function u6BossAnswer(answer){u6StopBoss();const b=u6BossDraft(),q=U6_UNIT_QUIZZES[u6Unit].post[b.round%4],correct=answer===q[2];if(correct){b.hits++;playRewardSound()}else b.misses++;b.round++;b.seconds=15;persist();const sprite=$('#u6-boss-sprite');if(sprite)sprite.classList.add(correct?'hurt':'attack');const flash=$('#u6-boss-flash');if(flash){flash.textContent=correct?'โดนแล้ว!':'ตั้งโล่!';flash.classList.add('show')}setTimeout(()=>{if(!currentRider||u6StageKind(u6Unit,u6Stage)!=='boss')return;if(b.round>=4||b.misses>=3)u6BossFinish(b.hits>=3);else u6BossTurn()},650)}
function u6BossFinish(won,skipped=false){u6StopBoss();const d=u6Data(u6Unit),b=u6BossDraft();if(!b.finished){b.finished=true;b.running=false;b.won=won;b.skipped=skipped;d.boss={won,hits:b.hits,misses:b.misses,skipped,at:new Date().toISOString()};state.battles.push({unit:u6Unit,mode:'mission',won,hits:b.hits,shots:b.round,score:b.hits*10,finishedAt:new Date().toISOString()});u6Record('boss',b.hits,4,{won,skipped});const old=d.stageScores[u6Stage]?.points||0,p=Math.round(10*b.hits/4);if(p>old){d.stageScores[u6Stage]={points:p,maxPoints:10,at:new Date().toISOString(),kind:'boss'};rewardBurst(p-old)}persist()}u6BossFinishView()}
function u6BossFinishView(){const b=u6BossDraft(),box=$('#u6-boss-controls');if(!box)return;$('#u6-boss-sprite')?.classList.add(b.won?'defeated':'ready');box.innerHTML=`<div class="u6-boss-call"><h3>${b.skipped?'พักเกมบอสไว้ก่อน':b.won?'ชนะแล้ว!':'ลองอีกครั้งได้'}</h3><p>โจมตีถูก ${b.hits}/4 ครั้ง · ได้ ${u6Data(u6Unit).stageScores[u6Stage]?.points||0}/10 พลัง</p><button class="primary" id="u6-boss-next">ดูผลบทนี้ →</button><button class="secondary" id="u6-boss-retry">ลองสู้ใหม่</button></div>`;$('#u6-boss-next').onclick=u6Next;$('#u6-boss-retry').onclick=()=>{u6Data(u6Unit).bossDraft=null;persist();u6RenderBoss()}}
function u6SummaryHTML(n){const d=u6Data(n),p=u6Plan(n),energy=Object.values(d.stageScores).reduce((v,x)=>v+(x.points||0),0),topic=Object.values(d.topicPre).reduce((v,x)=>v+(x.points||0),0),topicMax=p.topics.length;return `<div class="u6-summary"><div class="u6-result-pair"><div><small>ก่อนเรียน</small><strong>${d.pre?d.pre.points+'/4':'ยังไม่ทำ'}</strong></div><div><small>หลังเรียน</small><strong>${d.post?d.post.points+'/4':'ยังไม่ทำ'}</strong></div></div><div class="u6-unit-energy"><span>พลังภารกิจ ${n}</span><b>${energy}/${p.stages*10}</b></div><p>ก่อนเรียนรายเรื่อง ${topic}/${topicMax} · ทำแล้ว ${Object.keys(d.stageScores).length}/${p.stages} ด่าน</p><p>เกมบอส: ${d.boss?(d.boss.skipped?'ข้าม':d.boss.won?'ชนะ':'ลองอีกครั้งได้'):'ยังไม่เล่น'}</p><details><summary>ดูคะแนนรายด่าน</summary><div class="u6-stage-list">${Array.from({length:p.stages},(_,i)=>`<div><span>${i+1}. ${esc(u6StageLabel(n,i))}</span><b>${d.stageScores[i]?.points??'—'}/10</b></div>`).join('')}</div></details><p class="small">คะแนนของเราเก็บไว้ในห้องเรียนนี้</p></div>`}
function u6RenderSummary(){const d=u6Data(u6Unit);if(d.post&&!d.complete){d.complete=true;persist()}$('#u6-page').innerHTML=`<div class="u6-intro">${u6Img(u6Scene(u6Unit),'Techno ยินดีกับผู้เรียน','u6-scene')}<div><span class="academic-kicker">สรุปผลการเรียนรู้</span><h2>${esc(u6Plan(u6Unit).missionTitle)}</h2><p>ดูสิ่งที่เราทำได้ แล้วเลือกฝึกอีกครั้งได้</p></div></div>${u6SummaryHTML(u6Unit)}<div class="u6-actions"><button class="primary" id="u6-summary-map">กลับแผนที่ →</button><button class="secondary" id="u6-summary-retry">เล่นภารกิจอีกครั้ง</button></div>`;$('#u6-summary-map').onclick=renderMap;$('#u6-summary-retry').onclick=()=>u6Open(u6Unit,0)}
const u6OldMap=renderMap;
renderMap=function(){u6StopBoss();const out=u6OldMap.apply(this,arguments);if(!currentRider)return out;document.querySelectorAll('.compact-map [data-unit]').forEach(b=>{const n=Number(b.dataset.unit)+1,p=u6Plan(n),d=n===2?null:u6Data(n);b.classList.remove('locked');b.classList.add('available');b.removeAttribute('aria-disabled');const last=b.querySelector('div>span');if(last)last.textContent=n===2?`17 ด่าน · ${state.complete?'ผ่านแล้ว':Object.keys(state.stageScores||{}).length+' ด่านได้พลัง'}`:`${p.stages} ด่าน · ${d?.complete?'ผ่านแล้ว':Object.keys(d?.stageScores||{}).length+' ด่านได้พลัง'}`;const arrow=b.querySelector(':scope>b');if(arrow)arrow.textContent='→';b.onclick=()=>n===2?enterStage(0):u6Open(n,d?.stage||0)});const title=$('.compact-map-title span');if(title)title.textContent='ครบ 9 ภารกิจ · 117 ด่าน';const start=$('#start-btn');if(start){const n=state.activeUnit||2;start.textContent=`เล่นภารกิจ ${n} ต่อ →`;start.onclick=()=>n===2?resumeLesson():u6Open(n,u6Data(n).stage)}const scope=$('.scope-note');if(scope)scope.innerHTML='เลือกบทที่อยากเรียนได้ทุกบท · เริ่มทีละด่านหรือแตะตัวเลขข้ามไปด่านที่ต้องการ';const me=$('.kk-me');if(me){const stats=me.querySelectorAll('.kk-me-stat');let energy=energyTotal(),max=170;for(const n of [1,3,4,5,6,7,8,9]){const d=u6Data(n);energy+=Object.values(d.stageScores).reduce((sum,x)=>sum+(x.points||0),0);max+=u6StageCount(n)*10}if(stats[0])stats[0].innerHTML=`<span>ϟ</span><b>${energy}</b><small>/ ${max} พลังทุกบท</small>`;if(stats[1])stats[1].innerHTML=`<span>✓</span><b>${[1,3,4,5,6,7,8,9].filter(n=>u6Data(n).complete).length+(state.complete?1:0)}</b><small>/ 9 ภารกิจ</small>`;const btn=null;/* ปุ่มคะแนนใช้หน้าต่างรวมของ kk-features.js (มีตารางรายด่านทุกภารกิจ) */if(btn){btn.textContent='ผลทั้ง 9 บท';btn.onclick=()=>modal({title:'ผลทั้ง 9 ภารกิจ',body:`<div class="u6-overview">${ALL_UNITS_DATA.map((p,i)=>{const n=i+1,d=n===2?null:u6Data(n),points=n===2?energyTotal():Object.values(d.stageScores).reduce((sum,x)=>sum+(x.points||0),0),max=n===2?170:p.stages*10;return `<button data-u6-report="${n}"><span>ภารกิจ ${n} · ${esc(p.missionTitle)}</span><b>${points}/${max}</b></button>`}).join('')}</div>`});document.querySelectorAll('[data-u6-report]').forEach(x=>x.onclick=()=>{closeModal();if(Number(x.dataset.u6Report)===2)showUnitReport();else modal({title:`ผลภารกิจ ${x.dataset.u6Report}`,body:u6SummaryHTML(Number(x.dataset.u6Report))})})}}return out};
const u6OldOpenUnit=u6Open;
u6Open=function(n,stage=0){state.activeUnit=n;persist();return u6OldOpenUnit(n,stage)};
const u6OldEnterStage=enterStage;
enterStage=function(index){state.activeUnit=2;persist();return u6OldEnterStage(index)};
scopeAll=function(){modal({title:'ขอบเขต 9 ภารกิจ',body:`${ALL_UNITS_DATA.map((u,i)=>`<h3>ภารกิจ ${i+1} · ${esc(u.missionTitle)}</h3><p>${esc(u.academicTitle)} · ${u.stages} ด่าน</p><p>เทียบคู่มือ สสวท.: ${esc(u.guideTitle)}</p>`).join('')}`})};
$('#help-btn').onclick=()=>modal({title:'วิธีเล่นกับ Techno',body:'<ol class="checklist"><li>เลือกภารกิจ 1–9 จากแผนที่</li><li>ทำแบบทดสอบก่อนเรียน อ่านเนื้อหา แล้วรับภารกิจ</li><li>แตะภาพ กดลูกศร ค้นหา หรือวาดภาพตามโจทย์ของแต่ละด่าน</li><li>แตะตัวเลขบนไทม์ไลน์เพื่อเลือกด่าน หรือกดไปต่อเพื่อเรียนทีละด่าน</li><li>ทำหลังเรียน ดูผลรายบท แล้วสู้บอสเพื่อรับพลัง</li></ol><p>ปุ่ม “ฟังคำอธิบาย” ใช้เสียงภาษาไทยของเครื่อง หากไม่มีให้ครูช่วยอ่าน</p>'});
